#include <stdio.h>

int main(void) {
    int i = 1;

    while (i <= 5) {
        printf("Sorry %d\n", i);
        i++;
    }

    printf("Done! i is now %d\n", i);
    return 0;
}

#include <stdio.h>

int main(void) {
    int fish = 1;
    int day = 1;

    while (fish < 100) {
        fish = fish * 2;
        day++;
    }

    printf("Day %d: %d fish\n", day, fish);
    return 0;
}
